import { z } from "zod";
const cloudSummarySchema = z
    .object({
    cloudSummary: z.literal(true),
    experimentId: z.string().optional(),
    experimentUrl: z.string().optional(),
    testRunId: z.string().optional(),
    testRunUrl: z.string().optional(),
    counts: z.record(z.string(), z.number()).optional(),
})
    .passthrough();
export function parseCloudReplaySummary(stdout) {
    const starts = Array.from(stdout.matchAll(/^\{/gm), (match) => match.index);
    for (let i = starts.length - 1; i >= 0; i--) {
        const parsed = cloudSummarySchema.safeParse(parseJson(stdout.slice(starts[i])));
        if (parsed.success) {
            return parsed.data;
        }
    }
    return null;
}
export function buildCloudCompleteSummary(summary) {
    const counts = summary.counts ?? {};
    return {
        ...summary,
        itemCount: (counts.replayed ?? 0) + (counts.carriedOver ?? 0),
    };
}
function parseJson(text) {
    try {
        return JSON.parse(text);
    }
    catch {
        return undefined;
    }
}
